code='''from collections import Counter

def transform(grid):
    out = [row[:] for row in grid]
    counts = Counter(v for row in grid for v in row)
    background = counts.most_common(1)[0][0]
    colors = set(counts) - {background}
    h, w = len(grid), len(grid[0])
    for color in colors:
        # Connect consecutive occurrences in each row.
        for r in range(h):
            cols = [c for c, v in enumerate(grid[r]) if v == color]
            for a, b in zip(cols, cols[1:]):
                for c in range(a + 1, b):
                    out[r][c] = 3
        # Connect consecutive occurrences in each column.
        for c in range(w):
            rows = [r for r in range(h) if grid[r][c] == color]
            for a, b in zip(rows, rows[1:]):
                for r in range(a + 1, b):
                    out[r][c] = 3
    return out
'''
